const slots = $slots;
probe(Number.isInteger(slots.units) && slots.units > 0, "the stated stock must be a positive whole number of units");
probe(Number.isInteger(slots.dayCapacity) && slots.dayCapacity > 0, "the daily consumption must be a positive whole number of units");
probe(Number.isInteger(slots.arrivalDays) && slots.arrivalDays >= 0, "the delivery time must be a whole number of days");
probe(slots.arrivalDays < slots.dayCapacity, "the delivery time must exceed the daily consumption for the order to be placed today");
const days = Math.floor(slots.units / slots.dayCapacity);
const ordered = days + " days, " + slots.arrivalDays + " in the delivery.";
return ordered + ". The stock is " + days + " whole units.";

